INSERT OR IGNORE INTO `meta_build_items` (`item_key`, `title`, `detail`, `status`, `note`, `sort_order`, `created_at`, `updated_at`) VALUES ('sam31-key-vault', 'Founder API key vault & status', 'Founder-only settings field for the Meta Model API key (dev.meta.ai). The key is stored server-side, never hard-coded, and only a masked hint is ever shown. Until a key is saved, Privacy Blur keeps running on the built-in engine and says so.', 'done', 'Built Oct 29, 2026. Next step is Manny''s: create the key at dev.meta.ai and paste it in Meta AI → SAM 3.1 Lab.', 0, 1793293200000, 1793293200000);
--> statement-breakpoint
INSERT OR IGNORE INTO `meta_build_items` (`item_key`, `title`, `detail`, `status`, `note`, `sort_order`, `created_at`, `updated_at`) VALUES ('sam31-connection-test', 'Live connection test against api.meta.ai', 'Server-side check of the saved key against the Meta Model API model list, with honest outcomes: connected, invalid key, model_not_found (key valid but no SAM 3.1 access), or unreachable.', 'in_progress', 'Built Oct 29, 2026. Becomes done after the first successful test with a real key.', 1, 1793293200000, 1793293200000);
--> statement-breakpoint
INSERT OR IGNORE INTO `meta_build_items` (`item_key`, `title`, `detail`, `status`, `note`, `sort_order`, `created_at`, `updated_at`) VALUES ('sam31-image-lab', 'SAM 3.1 image segmentation lab', 'Upload a still image, send ONE concept phrase per request (person, face, dog, document…), and receive segmentation regions back from model sam-3.1. Every attempt — including no-key and model_not_found — is recorded in the job history.', 'in_progress', 'Built Oct 29, 2026. Needs a configured key with SAM 3.1 access to produce its first real masks.', 2, 1793293200000, 1793293200000);
--> statement-breakpoint
INSERT OR IGNORE INTO `meta_build_items` (`item_key`, `title`, `detail`, `status`, `note`, `sort_order`, `created_at`, `updated_at`) VALUES ('sam31-mask-renderer', 'Mask-accurate blur renderer (built-in interim)', 'The on-device video processor now composites blur through feathered alpha masks shaped to each tracked subject (ellipse for faces, soft blob for bodies/pets) instead of hard rectangles. This is SAM-style mask rendering with built-in detection — it is not SAM 3.1 output and is never labeled as such.', 'done', 'Shipped Oct 29, 2026 in privacyProcessor.ts; whole-frame and box fallbacks retained.', 3, 1793293200000, 1793293200000);
--> statement-breakpoint
INSERT OR IGNORE INTO `meta_build_items` (`item_key`, `title`, `detail`, `status`, `note`, `sort_order`, `created_at`, `updated_at`) VALUES ('sam31-video-pipeline', 'SAM 3.1 video mask pipeline', 'Send recorded clips (MP4/MOV H.264 — WebM/VP9 is not accepted by the API) for per-concept video segmentation, decode the returned masks, track them across frames, and burn mask blur into the stored copy. Limits: 15,000 frames, 16 tracked objects per frame.', 'not_started', 'Starts after the image lab verifies end-to-end with a real key.', 4, 1793293200000, 1793293200000);
--> statement-breakpoint
INSERT OR IGNORE INTO `meta_build_items` (`item_key`, `title`, `detail`, `status`, `note`, `sort_order`, `created_at`, `updated_at`) VALUES ('sam31-submit-integration', 'Wire SAM masks into task submissions', 'Protected care tasks use SAM-processed copies when the video pipeline is verified; built-in blur remains the automatic fallback and Privacy Blur stays locked on for childcare/caregiving either way.', 'not_started', NULL, 5, 1793293200000, 1793293200000);
--> statement-breakpoint
INSERT OR IGNORE INTO `meta_build_items` (`item_key`, `title`, `detail`, `status`, `note`, `sort_order`, `created_at`, `updated_at`) VALUES ('muse-nova-brain', 'Muse Spark for Nova''s brain (next Meta model)', 'Nova''s answers are currently a curated in-app knowledge base with recorded voice. The conversational upgrade routes Nova''s questions through a Meta Muse model after SAM 3.1 lands.', 'not_started', 'Queued behind SAM 3.1 per the founder''s build order.', 6, 1793293200000, 1793293200000);
--> statement-breakpoint
INSERT OR IGNORE INTO `meta_build_items` (`item_key`, `title`, `detail`, `status`, `note`, `sort_order`, `created_at`, `updated_at`) VALUES ('muse-image-art', 'Muse Image for character art (later)', 'Future character and training art generation with Meta''s Muse Image, after SAM 3.1 and Nova''s brain.', 'not_started', NULL, 7, 1793293200000, 1793293200000);
